  const pump = () => {
    drawFrame(canvas);
    if (_video.currentTime >= outT || _video.paused && _video.currentTime >= outT - 0.02) {
      _video.pause();
      _recorder.stop();
      cancelAnimationFrame(_rafId);
      return;
    }
    _rafId = requestAnimationFrame(pump);
  };

  _recorder.start();
  _video.play().then(() => { _rafId = requestAnimationFrame(pump); });
}
